var sel = uidoc.Selection.GetElementIds().Select(id => doc.GetElement(id)).ToList();
var texts = new FilteredElementCollector(doc, doc.ActiveView.Id).OfClass(typeof(TextNote)).Cast<TextNote>()
    .Select(t => new { t.Text, P = t.Coord }).ToList();
var labels = new List<object>();
foreach (var e in sel)
{
    var te = e as TextElement;
    XYZ pos = te != null ? te.Coord : null;
    string lbl = null;
    try { var p = e.get_Parameter(BuiltInParameter.ELEM_FAMILY_PARAM); lbl = p?.AsValueString(); } catch {}
    string sample = te != null ? te.Text : null;
    var near = pos == null ? null : texts.OrderBy(t => t.P.DistanceTo(pos)).Take(3)
        .Select(t => new { text = t.Text.Trim(), dxMm = Math.Round((t.P.X - pos.X) * 304.8), dyMm = Math.Round((t.P.Y - pos.Y) * 304.8) }).ToList();
    labels.Add(new {
        id = e.Id.IntegerValue, cls = e.GetType().Name,
        type = doc.GetElement(e.GetTypeId())?.Name,
        sampleText = sample,
        xMm = pos == null ? (double?)null : Math.Round(pos.X * 304.8), yMm = pos == null ? (double?)null : Math.Round(pos.Y * 304.8),
        nearbyCaptions = near
    });
}
var fm = doc.FamilyManager;
var famParams = fm.Parameters.Cast<FamilyParameter>().Select(p => new { name = p.Definition.Name, shared = p.IsShared, guid = p.IsShared ? p.GUID.ToString() : null, instance = p.IsInstance }).ToList();
return new { labels, famParams, sharedParamFile = app.SharedParametersFilename };
